class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        n = len(s)
        max_len = 0

        # Iterate through all possible starting positions i
        for i in range(n):
            # Iterate through all possible ending positions j
            for j in range(i, n):
                substring = s[i:j+1]

                # Helper function to check uniqueness O(L)
                if len(set(substring)) == len(substring):
                    max_len = max(max_len, len(substring))
                else:
                    # Optimization: If s[i:j+1] fails, s[i:j+2] will also fail.
                    # We can break the inner loop, but complexity remains cubic.
                    break

        return max_len

