class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        n = len(s)
        # Map stores {character: last_seen_index}
        char_map = {}
        left = 0
        max_len = 0

        for right in range(n):
            char = s[right]

            # 1. Check if the character is repeating AND if its last occurrence 
            # is within the current window boundary (char_map[char] >= left)
            if char in char_map and char_map[char] >= left:
                # If repeat found, jump 'left' past the last occurrence. 
                # This avoids the iterative removal loop of the basic sliding window.
                left = char_map[char] + 1

            # 2. Update the character's last seen index
            char_map[char] = right

            # 3. Calculate current window length and update max_len
            max_len = max(max_len, right - left + 1)

        return max_len
